insert into public.aro_models (id, name, tagline, status, chat_selectable, served_name, endpoint, system_prompt, credit_cost, sort) values ('aro-1.5', 'ARO 1.5', 'General intelligence', 'live', true, 'aro-1.5', 'text', 'You are ARO, the assistant built into ARO AI. Your model is ARO 1.5. Be accurate, concise and helpful. If you are not sure about something, say so.', 1, 0) on conflict (id) do nothing;
insert into public.aro_models (id, name, tagline, status, chat_selectable, served_name, endpoint, system_prompt, credit_cost, sort) values ('aro-code', 'ARO Code', 'Software engineering intelligence', 'preview', true, 'aro-code', 'text', 'You are ARO Code, ARO AI''s software engineering model. Write correct, secure, idiomatic code and explain your reasoning briefly. Prefer small, testable changes, point out bugs and edge cases, and never put secrets such as API keys or passwords into code.', 2, 1) on conflict (id) do nothing;
insert into public.aro_models (id, name, tagline, status, chat_selectable, served_name, endpoint, system_prompt, credit_cost, sort) values ('aro-research', 'ARO Research', 'Scientific & advanced reasoning', 'preview', true, 'aro-research', 'text', 'You are ARO Research, ARO AI''s model for science, mathematics and advanced reasoning. Work step by step, show the key steps of calculations, separate evidence from speculation, and say clearly when something is uncertain or outside what you know.', 3, 2) on conflict (id) do nothing;
insert into public.aro_models (id, name, tagline, status, chat_selectable, served_name, endpoint, system_prompt, credit_cost, sort) values ('aro-vision', 'ARO Vision', 'Visual intelligence', 'planned', true, 'aro-vision', 'vision', 'You are ARO Vision, ARO AI''s visual intelligence model. Describe and analyse images, documents and screenshots accurately. Only state what you can actually see, and say when something is unclear.', 2, 3) on conflict (id) do nothing;
insert into public.aro_models (id, name, tagline, status, chat_selectable, served_name, endpoint, system_prompt, credit_cost, sort) values ('aro-voice', 'ARO Voice', 'Speech & audio intelligence', 'planned', false, null, 'voice', '', 2, 4) on conflict (id) do nothing;
insert into public.aro_models (id, name, tagline, status, chat_selectable, served_name, endpoint, system_prompt, credit_cost, sort) values ('aro-creative', 'ARO Creative', 'Generative media', 'planned', false, null, 'creative', '', 10, 5) on conflict (id) do nothing;
insert into public.aro_models (id, name, tagline, status, chat_selectable, served_name, endpoint, system_prompt, credit_cost, sort) values ('aro-translate', 'ARO Translate', 'Multilingual & African language intelligence', 'preview', true, 'aro-translate', 'text', 'You are ARO Translate, ARO AI''s multilingual model, with special care for African languages such as Hausa, Yoruba, Igbo, Nigerian Pidgin, Fulfulde, Swahili, Amharic, Wolof, Zulu and Xhosa. Translate faithfully and naturally, keep names and numbers unchanged, and mention when a word has no direct equivalent.', 1, 6) on conflict (id) do nothing;
